 else if(/[\\d.]/.test(c)){while(i<source.length&&/[\\p{L}\\p{N}_.]/u.test(source[i]))i++;value=source.slice(start,i);if("'!/''^('"\\d+(\\.\\d+)?|\\.\\d+)"'$/.test(value))fail(t,'"'Niepoprawna liczba: '+value)}
 else if(/[\\p{L}_:]/u.test(c)){i++;while(i<source.length&&/[\\p{L}\\p{N}_:]/u.test(source[i]))i++;value=source.slice(start,i).toLowerCase()}
 else if('[](),+-*/<>= '.includes(c)){i++;if('<>'.includes(c)&&'='.includes(source[i]||'"'!'"'))i++;else if(c==='<'&&source[i]==='>')i++;value=source.slice(start,i)}else fail(t,'Nieznany znak: '+c);
 out.push({...t,v:value,end:i,binary:"'!['"'+','-','*','/'].includes(value)||(/\\s/.test(source[start-1]||' '))===(/\\s/.test(source[i]||' '))});column+=i-start;
 if(out.length>10000)fail(t,'Przekroczono limit 10 000 tokenów.');
