await page.click('#examplesNav');await page.click('#showHistory');assert.ok(await page.locator('[data-backup]').count()>0);await page.click('#closeModal');
await page.evaluate(()=>window.logomocja.open('powtorz 4 [np 100 pw 90]','2d'));await page.click('#challengesNav');await page.click('[data-challenge=\"0\"]');await page.click('#checkChallenge');assert.match(await page.locator('#challengeResult').textContent(),/Brawo/);await page.click('#closeModal');
await page.click('#referenceNav');assert.equal(await page.locator('.command-entry').count(),19);await page.fill('.reference-search','góra');assert.equal(await page.locator('.command-entry:visible').count(),1);await page.click('#closeModal');
