await page.setViewportSize({width:390,height:844});await page.evaluate(()=>window.logomocja.open('powtorz 12 [powtorz 4 [np 100 pw 90] pw 30]','2d'));await page.screenshot({path:'/tmp/logomocja-mobile.png',fullPage:true});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));
